import sqlite3 from 'sqlite3';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { dirname } from 'path';

const __dirname = dirname(fileURLToPath(import.meta.url));

const dbPath = process.env.DB_PATH || '/app/pellmoor.db';

// Use verbose mode for debugging
sqlite3.verbose();

const db = new sqlite3.Database(dbPath, (err) => {
  if (err) {
    console.error('Database connection error:', err);
    process.exit(1);
  }
  console.log('Connected to SQLite database at', dbPath);
});

// Enable foreign keys
db.run('PRAGMA foreign_keys = ON');

// Wrap db methods to use callbacks properly
const dbRun = (sql, params = []) =>
  new Promise((resolve, reject) => {
    db.run(sql, params, function (err) {
      if (err) reject(err);
      else resolve({ id: this.lastID, changes: this.changes });
    });
  });

const dbGet = (sql, params = []) =>
  new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });

const dbAll = (sql, params = []) =>
  new Promise((resolve, reject) => {
    db.all(sql, params, (err, rows) => {
      if (err) reject(err);
      else resolve(rows || []);
    });
  });

const dbExec = (sql) =>
  new Promise((resolve, reject) => {
    db.exec(sql, (err) => {
      if (err) reject(err);
      else resolve();
    });
  });

export async function initializeDatabase() {
  try {
    // Check if database already has tables
    const tables = await dbAll(
      "SELECT name FROM sqlite_master WHERE type='table'"
    );

    if (tables.length > 0) {
      console.log('Database already initialized');
      return;
    }

    console.log('Initializing database...');

    // Create tables
    await dbExec(`
      CREATE TABLE users (
        email TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        role TEXT NOT NULL,
        password_hash TEXT NOT NULL
      );

      CREATE TABLE sessions (
        token TEXT PRIMARY KEY,
        email TEXT NOT NULL,
        created_at TEXT NOT NULL,
        expires_at TEXT NOT NULL,
        FOREIGN KEY(email) REFERENCES users(email)
      );

      CREATE TABLE roles (
        code TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        team TEXT NOT NULL,
        openings INTEGER NOT NULL
      );

      CREATE TABLE candidates (
        id TEXT PRIMARY KEY,
        role_code TEXT NOT NULL,
        name TEXT NOT NULL,
        current_stage TEXT NOT NULL,
        assessment_version INTEGER NOT NULL DEFAULT 1,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        FOREIGN KEY(role_code) REFERENCES roles(code)
      );

      CREATE TABLE stage_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        candidate_id TEXT NOT NULL,
        stage TEXT NOT NULL,
        timestamp TEXT NOT NULL,
        FOREIGN KEY(candidate_id) REFERENCES candidates(id)
      );

      CREATE TABLE panels (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        candidate_id TEXT NOT NULL,
        assessment_version INTEGER NOT NULL,
        created_at TEXT NOT NULL,
        FOREIGN KEY(candidate_id) REFERENCES candidates(id)
      );

      CREATE TABLE panel_members (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        panel_id INTEGER NOT NULL,
        email TEXT NOT NULL,
        added_at TEXT NOT NULL,
        FOREIGN KEY(panel_id) REFERENCES panels(id),
        FOREIGN KEY(email) REFERENCES users(email)
      );

      CREATE TABLE scores (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        candidate_id TEXT NOT NULL,
        assessment_version INTEGER NOT NULL,
        panel_member_email TEXT NOT NULL,
        score INTEGER NOT NULL,
        recorded_at TEXT NOT NULL,
        FOREIGN KEY(candidate_id) REFERENCES candidates(id),
        FOREIGN KEY(panel_member_email) REFERENCES users(email),
        UNIQUE(candidate_id, assessment_version, panel_member_email)
      );

      CREATE TABLE notes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        candidate_id TEXT NOT NULL,
        author_email TEXT NOT NULL,
        content TEXT NOT NULL,
        created_at TEXT NOT NULL,
        FOREIGN KEY(candidate_id) REFERENCES candidates(id),
        FOREIGN KEY(author_email) REFERENCES users(email)
      );

      CREATE TABLE vacancy_revisions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        role_code TEXT NOT NULL,
        revision_number INTEGER NOT NULL,
        changed_by TEXT NOT NULL,
        change_reason TEXT NOT NULL,
        changed_at TEXT NOT NULL,
        FOREIGN KEY(role_code) REFERENCES roles(code),
        FOREIGN KEY(changed_by) REFERENCES users(email),
        UNIQUE(role_code, revision_number)
      );

      CREATE TABLE activity_trail (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        role_code TEXT NOT NULL,
        candidate_id TEXT NOT NULL,
        action_type TEXT NOT NULL,
        actor_email TEXT NOT NULL,
        action_data TEXT,
        batch_id TEXT,
        batch_position INTEGER,
        batch_total INTEGER,
        assessment_version_at_action INTEGER,
        assessment_version_changed BOOLEAN DEFAULT 0,
        created_at TEXT NOT NULL,
        FOREIGN KEY(role_code) REFERENCES roles(code),
        FOREIGN KEY(candidate_id) REFERENCES candidates(id),
        FOREIGN KEY(actor_email) REFERENCES users(email)
      );

      CREATE TABLE operation_receipts (
        operation_id TEXT NOT NULL,
        actor_email TEXT NOT NULL,
        role_code TEXT NOT NULL,
        operation_type TEXT NOT NULL,
        status TEXT NOT NULL,
        request_data TEXT NOT NULL,
        response_data TEXT,
        created_at TEXT NOT NULL,
        PRIMARY KEY(operation_id, actor_email),
        FOREIGN KEY(actor_email) REFERENCES users(email),
        FOREIGN KEY(role_code) REFERENCES roles(code)
      );

      CREATE INDEX idx_candidates_role ON candidates(role_code);
      CREATE INDEX idx_stage_history_candidate ON stage_history(candidate_id);
      CREATE INDEX idx_panels_candidate ON panels(candidate_id);
      CREATE INDEX idx_scores_candidate ON scores(candidate_id);
      CREATE INDEX idx_notes_candidate ON notes(candidate_id);
      CREATE INDEX idx_activity_vacancy ON activity_trail(role_code);
      CREATE INDEX idx_sessions_email ON sessions(email);
    `);

    console.log('Tables created successfully');

    // Load seed data
    await loadSeedData();
  } catch (err) {
    console.error('Database initialization error:', err);
    throw err;
  }
}

async function loadSeedData() {
  const seedPath = '/recruitment/records/pellmoor_seed_data.json';

  if (!fs.existsSync(seedPath)) {
    console.log('Seed data file not found at', seedPath);
    return;
  }

  const seedData = JSON.parse(fs.readFileSync(seedPath, 'utf-8'));
  const now = new Date().toISOString();

  try {
    // Hash seed password
    const crypto = await import('crypto');
    const passwordHash = crypto
      .createHash('sha256')
      .update(seedData.seed_password)
      .digest('hex');

    // Load users
    for (const person of seedData.people) {
      await dbRun(
        `INSERT OR IGNORE INTO users (email, name, role, password_hash)
         VALUES (?, ?, ?, ?)`,
        [person.email, person.name, person.role, passwordHash]
      );
    }

    // Load roles (vacancies)
    for (const role of seedData.roles) {
      await dbRun(
        `INSERT OR IGNORE INTO roles (code, title, team, openings)
         VALUES (?, ?, ?, ?)`,
        [role.code, role.title, role.team, role.openings]
      );
    }

    // Load candidates
    for (const candidate of seedData.candidates) {
      const appliedDate = new Date(seedData.clock);
      appliedDate.setDate(
        appliedDate.getDate() - candidate.days_since_applied
      );

      await dbRun(
        `INSERT OR IGNORE INTO candidates (id, role_code, name, current_stage, assessment_version, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [
          candidate.id,
          candidate.role,
          candidate.name,
          candidate.stage,
          1,
          appliedDate.toISOString(),
          now,
        ]
      );

      // Load stage history
      for (const stage of candidate.history) {
        // Use a simple timestamp progression for history
        const stageIndex = candidate.history.indexOf(stage);
        const stageDate = new Date(appliedDate);
        stageDate.setDate(stageDate.getDate() + stageIndex);

        await dbRun(
          `INSERT INTO stage_history (candidate_id, stage, timestamp)
           VALUES (?, ?, ?)`,
          [candidate.id, stage, stageDate.toISOString()]
        );
      }
    }

    // Load panels
    const panelMap = new Map();
    for (const panel of seedData.panels) {
      const panelResult = await dbRun(
        `INSERT INTO panels (candidate_id, assessment_version, created_at)
         VALUES (?, ?, ?)`,
        [panel.candidate, 1, now]
      );
      panelMap.set(panel.candidate, panelResult.id);

      for (const member of panel.members) {
        await dbRun(
          `INSERT INTO panel_members (panel_id, email, added_at)
           VALUES (?, ?, ?)`,
          [panelResult.id, member, now]
        );
      }
    }

    // Load scores
    for (const score of seedData.scores) {
      await dbRun(
        `INSERT INTO scores (candidate_id, assessment_version, panel_member_email, score, recorded_at)
         VALUES (?, ?, ?, ?, ?)`,
        [score.candidate, 1, score.panel_member, score.score, now]
      );
    }

    // Initialize vacancy revisions to 1 for each role
    for (const role of seedData.roles) {
      await dbRun(
        `INSERT OR IGNORE INTO vacancy_revisions (role_code, revision_number, changed_by, change_reason, changed_at)
         VALUES (?, ?, ?, ?, ?)`,
        [
          role.code,
          1,
          'system',
          'Database initialization',
          now,
        ]
      );
    }

    console.log('Seed data loaded successfully');
  } catch (err) {
    console.error('Error loading seed data:', err);
    throw err;
  }
}

export { db, dbRun, dbGet, dbAll, dbExec };

import crypto from 'crypto';
import { dbRun, dbGet } from './database.js';

const SESSION_DURATION_MS = 24 * 60 * 60 * 1000; // 24 hours

export function hashPassword(password) {
  return crypto.createHash('sha256').update(password).digest('hex');
}

export async function createSession(email) {
  const token = crypto.randomBytes(32).toString('hex');
  const now = new Date();
  const expiresAt = new Date(now.getTime() + SESSION_DURATION_MS);

  await dbRun(
    `INSERT INTO sessions (token, email, created_at, expires_at)
     VALUES (?, ?, ?, ?)`,
    [token, email, now.toISOString(), expiresAt.toISOString()]
  );

  return token;
}

export async function validateSession(token) {
  if (!token) return null;

  const session = await dbGet(
    `SELECT s.email, u.name, u.role
     FROM sessions s
     JOIN users u ON s.email = u.email
     WHERE s.token = ? AND s.expires_at > datetime('now')`,
    [token]
  );

  return session || null;
}

export async function revokeSession(token) {
  await dbRun(`DELETE FROM sessions WHERE token = ?`, [token]);
}

export async function authenticateUser(email, password) {
  const passwordHash = hashPassword(password);
  const user = await dbGet(
    `SELECT email, name, role FROM users WHERE email = ? AND password_hash = ?`,
    [email, passwordHash]
  );

  return user || null;
}

export function sessionMiddleware(req, res, next) {
  const authHeader = req.get('Authorization');
  const token = authHeader && authHeader.startsWith('Bearer ')
    ? authHeader.slice(7)
    : null;

  req.sessionToken = token;
  req.user = null;

  if (token) {
    validateSession(token).then((session) => {
      req.user = session;
      next();
    });
  } else {
    next();
  }
}

export function requireAuth(req, res, next) {
  if (!req.user) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

import { dbGet, dbAll, dbRun } from './database.js';

const STAGES = ['applied', 'screening', 'interview', 'offer', 'hired'];
const TERMINAL_STAGES = ['rejected', 'withdrawn'];
const ALL_STAGES = [...STAGES, ...TERMINAL_STAGES];
const SCORE_RANGE = [1, 5];
const MIN_PANEL = 2;

// Permissions
const PERMISSIONS = {
  hiring_manager: {
    moveCandidate: true,
    addNote: true,
    batchOffer: true,
  },
  coordinator: {
    addCandidate: true,
    addPanelMember: true,
    removePanelMember: true,
    addNote: true,
  },
  panel: {
    scoreCandidate: true,
    addNote: true,
  },
};

export async function canMoveCandidate(userRole) {
  return userRole === 'hiring manager';
}

export async function canAddPanelMember(userRole, userEmail) {
  if (userRole !== 'coordinator') return false;
  // Coordinator cannot be a panel member
  return userEmail !== 'coord@pellmoor.test';
}

export async function canRemovePanelMember(userRole) {
  return userRole === 'coordinator';
}

export async function canScoreCandidate(userRole) {
  return userRole === 'panel';
}

export async function canAddCandidate(userRole) {
  return userRole === 'coordinator';
}

export async function canBatchOffer(userRole) {
  return userRole === 'hiring manager';
}

export async function canAddNote() {
  return true; // Everyone can add notes
}

export async function isValidStageTransition(currentStage, nextStage) {
  // Terminal stages are terminal
  if (TERMINAL_STAGES.includes(currentStage)) {
    return false;
  }

  // Must be a valid stage
  if (!ALL_STAGES.includes(nextStage)) {
    return false;
  }

  // Can only move back one stage
  const currentIndex = STAGES.indexOf(currentStage);
  const nextIndex = STAGES.indexOf(nextStage);

  if (nextIndex === currentIndex + 1) {
    // Moving forward
    return true;
  }

  if (nextIndex === currentIndex - 1) {
    // Moving back one stage
    return true;
  }

  // Terminal stages
  if (TERMINAL_STAGES.includes(nextStage) && nextIndex >= 0) {
    // Can move to rejected/withdrawn from any pipeline stage
    return true;
  }

  return false;
}

export async function isPanelEligible(email, userRole) {
  // Only Ruth, Otis, and Wren can be panel members
  // Cal (coordinator) cannot be assigned
  const eligibleEmails = [
    'hiring@pellmoor.test', // Ruth
    'panel1@pellmoor.test', // Otis
    'panel2@pellmoor.test', // Wren
  ];

  return eligibleEmails.includes(email);
}

export async function canAddPanelAtStage(stage) {
  // Can add/remove panels only at applied, screening, or interview
  return ['applied', 'screening', 'interview'].includes(stage);
}

export async function canScoreAtStage(stage) {
  // Can only score at interview
  return stage === 'interview';
}

export async function hasMinimumPanel(panelMembers) {
  return panelMembers.length >= MIN_PANEL;
}

export async function hasNonHiringManagerOnPanel(panelMembers) {
  // At least one panel member must not be the hiring manager
  return panelMembers.some((email) => email !== 'hiring@pellmoor.test');
}

export async function isHiringManagerOnly(panelMembers) {
  // Check if panel consists only of hiring manager
  return (
    panelMembers.length === 1 &&
    panelMembers[0] === 'hiring@pellmoor.test'
  );
}

export async function getCompletePanelWithScores(candidateId, assessmentVersion) {
  // Get panel for candidate at specific assessment version
  const panel = await dbGet(
    `SELECT p.id FROM panels p
     WHERE p.candidate_id = ? AND p.assessment_version = ?`,
    [candidateId, assessmentVersion]
  );

  if (!panel) {
    return null;
  }

  const members = await dbAll(
    `SELECT email FROM panel_members WHERE panel_id = ?`,
    [panel.id]
  );

  if (members.length < MIN_PANEL) {
    return null;
  }

  const scores = await dbAll(
    `SELECT panel_member_email, score FROM scores
     WHERE candidate_id = ? AND assessment_version = ?`,
    [candidateId, assessmentVersion]
  );

  const memberEmails = members.map((m) => m.email);

  // Check if all panel members have scores
  const scoredMembers = scores.map((s) => s.panel_member_email);
  const allScored = memberEmails.every((email) =>
    scoredMembers.includes(email)
  );

  if (!allScored) {
    return null;
  }

  // Check for hiring manager only panel
  const hasNonHiringManager = memberEmails.some(
    (email) => email !== 'hiring@pellmoor.test'
  );
  if (!hasNonHiringManager) {
    return null;
  }

  return { members: memberEmails, scores };
}

export async function calculateVacancyCapacity(roleCode) {
  // Get total openings
  const role = await dbGet(
    `SELECT openings FROM roles WHERE code = ?`,
    [roleCode]
  );

  if (!role) {
    return null;
  }

  const total = role.openings;

  // Count filled (hired)
  const filled = await dbGet(
    `SELECT COUNT(*) as count FROM candidates
     WHERE role_code = ? AND current_stage = 'hired'`,
    [roleCode]
  );

  // Count reserved (offer)
  const reserved = await dbGet(
    `SELECT COUNT(*) as count FROM candidates
     WHERE role_code = ? AND current_stage = 'offer'`,
    [roleCode]
  );

  const filledCount = filled?.count || 0;
  const reservedCount = reserved?.count || 0;
  const availableCount = Math.max(0, total - filledCount - reservedCount);

  return {
    total,
    filled: filledCount,
    reserved: reservedCount,
    available: availableCount,
  };
}

export async function canTransitionToOffer(candidateId, assessmentVersion, roleCode) {
  // Check: must have complete current assessment
  const complete = await getCompletePanelWithScores(candidateId, assessmentVersion);
  if (!complete) {
    return { allowed: false, reason: 'Incomplete assessment' };
  }

  // Check: must have available capacity
  const capacity = await calculateVacancyCapacity(roleCode);
  if (capacity.available <= 0) {
    return { allowed: false, reason: 'No available openings' };
  }

  return { allowed: true };
}

export async function calculateFunnel(roleCode) {
  // Get all candidates for this role
  const candidates = await dbAll(
    `SELECT id, current_stage FROM candidates WHERE role_code = ?`,
    [roleCode]
  );

  // Get all stage histories
  const histories = await Promise.all(
    candidates.map(async (c) => {
      const history = await dbAll(
        `SELECT stage FROM stage_history WHERE candidate_id = ? ORDER BY timestamp ASC`,
        [c.id]
      );
      return {
        id: c.id,
        currentStage: c.current_stage,
        history: history.map((h) => h.stage),
      };
    })
  );

  // Calculate funnel: reached count, remaining count, lost count at each stage
  const funnel = {};
  for (const stage of STAGES) {
    funnel[stage] = {
      reached: 0,
      remaining: 0,
      lost: 0,
    };
  }

  for (const candidate of histories) {
    // Count reached stages
    const visitedStages = new Set();
    for (const stage of candidate.history) {
      if (STAGES.includes(stage)) {
        visitedStages.add(stage);
        funnel[stage].reached++;
      }
    }

    // Determine if lost and at which stage
    const isTerminal = TERMINAL_STAGES.includes(candidate.currentStage);
    if (isTerminal) {
      // Lost - find the last pipeline stage visited before terminal
      const lastPipelineStage = [...candidate.history]
        .reverse()
        .find((stage) => STAGES.includes(stage));

      if (lastPipelineStage) {
        funnel[lastPipelineStage].lost++;
      }
    } else {
      // Still in pipeline - remaining at current stage
      if (STAGES.includes(candidate.currentStage)) {
        funnel[candidate.currentStage].remaining++;
      }
    }
  }

  return funnel;
}

export async function validatePanelAddition(
  candidateId,
  memberEmail,
  currentAssessmentVersion
) {
  const candidate = await dbGet(
    `SELECT current_stage FROM candidates WHERE id = ?`,
    [candidateId]
  );

  if (!candidate) {
    return { valid: false, error: 'Candidate not found' };
  }

  if (!(await canAddPanelAtStage(candidate.current_stage))) {
    return { valid: false, error: 'Cannot add panel at this stage' };
  }

  if (!(await isPanelEligible(memberEmail))) {
    return { valid: false, error: 'Panel member not eligible' };
  }

  // Check if already on panel
  const existingPanel = await dbGet(
    `SELECT pm.id FROM panel_members pm
     JOIN panels p ON pm.panel_id = p.id
     WHERE p.candidate_id = ? AND p.assessment_version = ? AND pm.email = ?`,
    [candidateId, currentAssessmentVersion, memberEmail]
  );

  if (existingPanel) {
    return { valid: false, error: 'Member already on panel' };
  }

  return { valid: true };
}

export async function validateScore(
  score,
  candidateId,
  stage,
  panelMemberEmail
) {
  if (!Number.isInteger(score)) {
    return { valid: false, error: 'Score must be an integer' };
  }

  if (score < SCORE_RANGE[0] || score > SCORE_RANGE[1]) {
    return {
      valid: false,
      error: `Score must be between ${SCORE_RANGE[0]} and ${SCORE_RANGE[1]}`,
    };
  }

  if (!(await canScoreAtStage(stage))) {
    return { valid: false, error: 'Can only score at interview stage' };
  }

  return { valid: true };
}

import express from 'express';
import { authenticateUser, createSession, revokeSession, validateSession } from './auth.js';
import { requireAuth } from './auth.js';

const router = express.Router();

// Login endpoint
router.post('/auth/login', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  try {
    const user = await authenticateUser(email, password);

    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const token = await createSession(email);

    res.json({
      token,
      user: {
        email: user.email,
        name: user.name,
        role: user.role,
      },
    });
  } catch (err) {
    console.error('Login error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Logout endpoint
router.post('/auth/logout', requireAuth, async (req, res) => {
  try {
    await revokeSession(req.sessionToken);
    res.json({ success: true });
  } catch (err) {
    console.error('Logout error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Check session endpoint
router.get('/auth/session', async (req, res) => {
  const authHeader = req.get('Authorization');
  const token = authHeader && authHeader.startsWith('Bearer ')
    ? authHeader.slice(7)
    : null;

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const session = await validateSession(token);

    if (!session) {
      return res.status(401).json({ error: 'Invalid or expired session' });
    }

    res.json({
      user: {
        email: session.email,
        name: session.name,
        role: session.role,
      },
    });
  } catch (err) {
    console.error('Session check error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

export default router;

import express from 'express';
import { requireAuth } from './auth.js';
import { dbGet, dbAll, dbRun } from './database.js';
import {
  calculateVacancyCapacity,
  calculateFunnel,
  canMoveCandidate,
  isValidStageTransition,
  canTransitionToOffer,
  canAddCandidate,
} from './hiring-rules.js';

const router = express.Router();

// Get all vacancies with current state
router.get('/api/vacancies', requireAuth, async (req, res) => {
  try {
    const roles = await dbAll(`SELECT * FROM roles ORDER BY code`);

    const vacancies = await Promise.all(
      roles.map(async (role) => {
        const capacity = await calculateVacancyCapacity(role.code);
        const funnel = await calculateFunnel(role.code);

        // Get current revision
        const revision = await dbGet(
          `SELECT revision_number FROM vacancy_revisions
           WHERE role_code = ? ORDER BY revision_number DESC LIMIT 1`,
          [role.code]
        );

        // Count candidates by stage
        const stageCounts = {};
        for (const stage of [
          'applied',
          'screening',
          'interview',
          'offer',
          'hired',
          'rejected',
          'withdrawn',
        ]) {
          const count = await dbGet(
            `SELECT COUNT(*) as count FROM candidates
             WHERE role_code = ? AND current_stage = ?`,
            [role.code, stage]
          );
          stageCounts[stage] = count?.count || 0;
        }

        return {
          code: role.code,
          title: role.title,
          team: role.team,
          openings: role.openings,
          revision: revision?.revision_number || 1,
          capacity,
          funnel,
          stageCounts,
        };
      })
    );

    res.json({ vacancies });
  } catch (err) {
    console.error('Error fetching vacancies:', err);
    res.status(500).json({ error: 'Failed to fetch vacancies' });
  }
});

// Get specific vacancy details
router.get('/api/vacancies/:roleCode', requireAuth, async (req, res) => {
  const { roleCode } = req.params;

  try {
    const role = await dbGet(`SELECT * FROM roles WHERE code = ?`, [roleCode]);

    if (!role) {
      return res.status(404).json({ error: 'Vacancy not found' });
    }

    const candidates = await dbAll(
      `SELECT * FROM candidates WHERE role_code = ? ORDER BY created_at DESC`,
      [roleCode]
    );

    const capacity = await calculateVacancyCapacity(roleCode);
    const funnel = await calculateFunnel(roleCode);

    const revision = await dbGet(
      `SELECT revision_number FROM vacancy_revisions
       WHERE role_code = ? ORDER BY revision_number DESC LIMIT 1`,
      [roleCode]
    );

    // Get full candidate details
    const candidateDetails = await Promise.all(
      candidates.map(async (candidate) => {
        const history = await dbAll(
          `SELECT stage, timestamp FROM stage_history
           WHERE candidate_id = ? ORDER BY timestamp ASC`,
          [candidate.id]
        );

        const notes = await dbAll(
          `SELECT n.id, n.content, n.author_email, u.name as author_name, n.created_at
           FROM notes n
           JOIN users u ON n.author_email = u.email
           WHERE n.candidate_id = ? ORDER BY n.created_at ASC`,
          [candidate.id]
        );

        return {
          id: candidate.id,
          name: candidate.name,
          currentStage: candidate.current_stage,
          assessmentVersion: candidate.assessment_version,
          createdAt: candidate.created_at,
          updatedAt: candidate.updated_at,
          history: history.map((h) => ({
            stage: h.stage,
            timestamp: h.timestamp,
          })),
          notes,
        };
      })
    );

    res.json({
      vacancy: {
        code: role.code,
        title: role.title,
        team: role.team,
        openings: role.openings,
        revision: revision?.revision_number || 1,
        capacity,
        funnel,
        candidates: candidateDetails,
      },
    });
  } catch (err) {
    console.error('Error fetching vacancy:', err);
    res.status(500).json({ error: 'Failed to fetch vacancy' });
  }
});

// Move candidate to next stage
router.post('/api/vacancies/:roleCode/candidates/:candidateId/move', requireAuth, async (req, res) => {
  const { roleCode, candidateId } = req.params;
  const { nextStage, expectedRevision } = req.body;

  // Check permissions
  const canMove = await canMoveCandidate(req.user.role);
  if (!canMove) {
    return res.status(403).json({ error: 'Unauthorized' });
  }

  try {
    // Get current candidate state
    const candidate = await dbGet(
      `SELECT * FROM candidates WHERE id = ? AND role_code = ?`,
      [candidateId, roleCode]
    );

    if (!candidate) {
      return res.status(404).json({ error: 'Candidate not found' });
    }

    // Get current revision
    const revisionResult = await dbGet(
      `SELECT revision_number FROM vacancy_revisions
       WHERE role_code = ? ORDER BY revision_number DESC LIMIT 1`,
      [roleCode]
    );

    const currentRevision = revisionResult?.revision_number || 1;

    if (expectedRevision !== undefined && expectedRevision !== currentRevision) {
      // Stale revision - return current state
      const currentState = await dbGet(
        `SELECT current_stage FROM candidates WHERE id = ?`,
        [candidateId]
      );

      const capacity = await calculateVacancyCapacity(roleCode);

      return res.status(409).json({
        error: 'Stale revision',
        currentRevision,
        currentStage: currentState?.current_stage,
        capacity,
      });
    }

    // Validate stage transition
    if (!isValidStageTransition(candidate.current_stage, nextStage)) {
      return res.status(400).json({
        error: 'Invalid stage transition',
        from: candidate.current_stage,
        to: nextStage,
      });
    }

    // Special checks for moving to offer
    if (nextStage === 'offer') {
      const canOffer = await canTransitionToOffer(
        candidateId,
        candidate.assessment_version,
        roleCode
      );

      if (!canOffer.allowed) {
        return res.status(400).json({
          error: canOffer.reason,
          currentRevision,
        });
      }
    }

    // Update candidate stage
    const now = new Date().toISOString();

    // Check if moving to interview - increment assessment version
    let newAssessmentVersion = candidate.assessment_version;
    let versionChanged = false;

    if (nextStage === 'interview' && candidate.current_stage !== 'interview') {
      newAssessmentVersion = candidate.assessment_version + 1;
      versionChanged = true;
    }

    // Add to stage history
    await dbRun(
      `INSERT INTO stage_history (candidate_id, stage, timestamp)
       VALUES (?, ?, ?)`,
      [candidateId, nextStage, now]
    );

    // Update candidate
    await dbRun(
      `UPDATE candidates
       SET current_stage = ?, assessment_version = ?, updated_at = ?
       WHERE id = ?`,
      [nextStage, newAssessmentVersion, now, candidateId]
    );

    // Increment vacancy revision
    const newRevision = currentRevision + 1;
    await dbRun(
      `INSERT INTO vacancy_revisions (role_code, revision_number, changed_by, change_reason, changed_at)
       VALUES (?, ?, ?, ?, ?)`,
      [roleCode, newRevision, req.user.email, `Stage change: ${candidate.current_stage} -> ${nextStage}`, now]
    );

    // Record activity
    await dbRun(
      `INSERT INTO activity_trail (role_code, candidate_id, action_type, actor_email, action_data, assessment_version_at_action, assessment_version_changed, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        roleCode,
        candidateId,
        'stage_change',
        req.user.email,
        JSON.stringify({ from: candidate.current_stage, to: nextStage }),
        candidate.assessment_version,
        versionChanged ? 1 : 0,
        now,
      ]
    );

    const capacity = await calculateVacancyCapacity(roleCode);

    res.json({
      success: true,
      candidate: {
        id: candidateId,
        currentStage: nextStage,
        assessmentVersion: newAssessmentVersion,
      },
      revision: newRevision,
      capacity,
    });
  } catch (err) {
    console.error('Error moving candidate:', err);
    res.status(500).json({ error: 'Failed to move candidate' });
  }
});

// Add candidate
router.post('/api/vacancies/:roleCode/candidates', requireAuth, async (req, res) => {
  const { roleCode } = req.params;
  const { name } = req.body;

  // Check permissions
  const canAdd = await canAddCandidate(req.user.role);
  if (!canAdd) {
    return res.status(403).json({ error: 'Unauthorized' });
  }

  if (!name || typeof name !== 'string') {
    return res.status(400).json({ error: 'Invalid candidate name' });
  }

  try {
    // Verify role exists
    const role = await dbGet(`SELECT * FROM roles WHERE code = ?`, [roleCode]);
    if (!role) {
      return res.status(404).json({ error: 'Vacancy not found' });
    }

    // Check if candidate already exists for this role
    const existing = await dbGet(
      `SELECT id FROM candidates WHERE role_code = ? AND name = ?`,
      [roleCode, name]
    );

    if (existing) {
      return res.status(400).json({ error: 'Candidate already exists for this role' });
    }

    const candidateId = `CAND-${Date.now()}-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;
    const now = new Date().toISOString();

    // Create candidate
    await dbRun(
      `INSERT INTO candidates (id, role_code, name, current_stage, assessment_version, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [candidateId, roleCode, name, 'applied', 1, now, now]
    );

    // Add initial stage history
    await dbRun(
      `INSERT INTO stage_history (candidate_id, stage, timestamp)
       VALUES (?, ?, ?)`,
      [candidateId, 'applied', now]
    );

    // Get current revision and increment
    const revisionResult = await dbGet(
      `SELECT revision_number FROM vacancy_revisions
       WHERE role_code = ? ORDER BY revision_number DESC LIMIT 1`,
      [roleCode]
    );

    const currentRevision = revisionResult?.revision_number || 1;
    const newRevision = currentRevision + 1;

    await dbRun(
      `INSERT INTO vacancy_revisions (role_code, revision_number, changed_by, change_reason, changed_at)
       VALUES (?, ?, ?, ?, ?)`,
      [roleCode, newRevision, req.user.email, 'Candidate added', now]
    );

    // Record activity
    await dbRun(
      `INSERT INTO activity_trail (role_code, candidate_id, action_type, actor_email, action_data, created_at)
       VALUES (?, ?, ?, ?, ?, ?)`,
      [roleCode, candidateId, 'candidate_added', req.user.email, JSON.stringify({ name }), now]
    );

    res.json({
      success: true,
      candidate: {
        id: candidateId,
        name,
        currentStage: 'applied',
        assessmentVersion: 1,
      },
      revision: newRevision,
    });
  } catch (err) {
    console.error('Error adding candidate:', err);
    res.status(500).json({ error: 'Failed to add candidate' });
  }
});

export default router;

import express from 'express';
import { requireAuth } from './auth.js';
import { dbGet, dbAll, dbRun } from './database.js';
import {
  canRemovePanelMember,
  canScoreCandidate,
  validatePanelAddition,
  validateScore,
  canAddPanelAtStage,
  isPanelEligible,
  getCompletePanelWithScores,
} from './hiring-rules.js';

const router = express.Router();

// Get panel for candidate
router.get('/api/candidates/:candidateId/panel', requireAuth, async (req, res) => {
  const { candidateId } = req.params;

  try {
    const candidate = await dbGet(
      `SELECT * FROM candidates WHERE id = ?`,
      [candidateId]
    );

    if (!candidate) {
      return res.status(404).json({ error: 'Candidate not found' });
    }

    const panel = await dbGet(
      `SELECT id FROM panels
       WHERE candidate_id = ? AND assessment_version = ?`,
      [candidateId, candidate.assessment_version]
    );

    if (!panel) {
      res.json({
        panel: null,
        assessmentVersion: candidate.assessment_version,
      });
      return;
    }

    const members = await dbAll(
      `SELECT pm.id, pm.email, u.name, pm.added_at
       FROM panel_members pm
       JOIN users u ON pm.email = u.email
       WHERE pm.panel_id = ?`,
      [panel.id]
    );

    const scores = await dbAll(
      `SELECT panel_member_email, score, recorded_at
       FROM scores
       WHERE candidate_id = ? AND assessment_version = ?`,
      [candidateId, candidate.assessment_version]
    );

    const memberScores = members.map((m) => {
      const score = scores.find((s) => s.panel_member_email === m.email);
      return {
        id: m.id,
        email: m.email,
        name: m.name,
        addedAt: m.added_at,
        score: score?.score || null,
        scoredAt: score?.recorded_at || null,
      };
    });

    res.json({
      panel: {
        id: panel.id,
        members: memberScores,
      },
      assessmentVersion: candidate.assessment_version,
      canEdit: ['applied', 'screening', 'interview'].includes(candidate.current_stage),
    });
  } catch (err) {
    console.error('Error fetching panel:', err);
    res.status(500).json({ error: 'Failed to fetch panel' });
  }
});

// Add panel member
router.post(
  '/api/candidates/:candidateId/panel/add',
  requireAuth,
  async (req, res) => {
    const { candidateId } = req.params;
    const { memberEmail, expectedRevision } = req.body;

    // Check permissions
    if (req.user.role !== 'coordinator') {
      return res.status(403).json({ error: 'Unauthorized' });
    }

    if (!memberEmail || typeof memberEmail !== 'string') {
      return res.status(400).json({ error: 'Invalid member email' });
    }

    try {
      const candidate = await dbGet(
        `SELECT * FROM candidates WHERE id = ?`,
        [candidateId]
      );

      if (!candidate) {
        return res.status(404).json({ error: 'Candidate not found' });
      }

      // Validate panel addition
      const validation = await validatePanelAddition(
        candidateId,
        memberEmail,
        candidate.assessment_version
      );

      if (!validation.valid) {
        return res.status(400).json({ error: validation.error });
      }

      // Check if member is eligible
      if (!(await isPanelEligible(memberEmail))) {
        return res.status(400).json({ error: 'Panel member not eligible' });
      }

      const now = new Date().toISOString();

      // Get or create panel for this assessment version
      let panel = await dbGet(
        `SELECT id FROM panels
         WHERE candidate_id = ? AND assessment_version = ?`,
        [candidateId, candidate.assessment_version]
      );

      if (!panel) {
        const result = await dbRun(
          `INSERT INTO panels (candidate_id, assessment_version, created_at)
           VALUES (?, ?, ?)`,
          [candidateId, candidate.assessment_version, now]
        );
        panel = { id: result.id };
      }

      // Add member
      await dbRun(
        `INSERT INTO panel_members (panel_id, email, added_at)
         VALUES (?, ?, ?)`,
        [panel.id, memberEmail, now]
      );

      // Increment assessment version for panel change
      const newVersion = candidate.assessment_version + 1;

      await dbRun(
        `UPDATE candidates
         SET assessment_version = ?, updated_at = ?
         WHERE id = ?`,
        [newVersion, now, candidateId]
      );

      // Increment vacancy revision
      const revisionResult = await dbGet(
        `SELECT revision_number FROM vacancy_revisions
         WHERE role_code = ? ORDER BY revision_number DESC LIMIT 1`,
        [candidate.role_code]
      );

      const currentRevision = revisionResult?.revision_number || 1;
      const newRevision = currentRevision + 1;

      await dbRun(
        `INSERT INTO vacancy_revisions (role_code, revision_number, changed_by, change_reason, changed_at)
         VALUES (?, ?, ?, ?, ?)`,
        [
          candidate.role_code,
          newRevision,
          req.user.email,
          'Panel member added',
          now,
        ]
      );

      // Record activity
      await dbRun(
        `INSERT INTO activity_trail (role_code, candidate_id, action_type, actor_email, action_data, assessment_version_at_action, assessment_version_changed, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          candidate.role_code,
          candidateId,
          'panel_member_added',
          req.user.email,
          JSON.stringify({ memberEmail }),
          candidate.assessment_version,
          1,
          now,
        ]
      );

      res.json({
        success: true,
        assessmentVersion: newVersion,
        revision: newRevision,
      });
    } catch (err) {
      console.error('Error adding panel member:', err);
      res.status(500).json({ error: 'Failed to add panel member' });
    }
  }
);

// Remove panel member
router.post(
  '/api/candidates/:candidateId/panel/remove',
  requireAuth,
  async (req, res) => {
    const { candidateId } = req.params;
    const { memberId, expectedRevision } = req.body;

    // Check permissions
    if (req.user.role !== 'coordinator') {
      return res.status(403).json({ error: 'Unauthorized' });
    }

    if (!memberId) {
      return res.status(400).json({ error: 'Invalid member ID' });
    }

    try {
      const candidate = await dbGet(
        `SELECT * FROM candidates WHERE id = ?`,
        [candidateId]
      );

      if (!candidate) {
        return res.status(404).json({ error: 'Candidate not found' });
      }

      if (!(await canAddPanelAtStage(candidate.current_stage))) {
        return res.status(400).json({
          error: 'Cannot modify panel at this stage',
        });
      }

      // Get member
      const member = await dbGet(
        `SELECT * FROM panel_members WHERE id = ?`,
        [memberId]
      );

      if (!member) {
        return res.status(404).json({ error: 'Panel member not found' });
      }

      // Remove member
      await dbRun(`DELETE FROM panel_members WHERE id = ?`, [memberId]);

      const now = new Date().toISOString();

      // Increment assessment version for panel change
      const newVersion = candidate.assessment_version + 1;

      await dbRun(
        `UPDATE candidates
         SET assessment_version = ?, updated_at = ?
         WHERE id = ?`,
        [newVersion, now, candidateId]
      );

      // Increment vacancy revision
      const revisionResult = await dbGet(
        `SELECT revision_number FROM vacancy_revisions
         WHERE role_code = ? ORDER BY revision_number DESC LIMIT 1`,
        [candidate.role_code]
      );

      const currentRevision = revisionResult?.revision_number || 1;
      const newRevision = currentRevision + 1;

      await dbRun(
        `INSERT INTO vacancy_revisions (role_code, revision_number, changed_by, change_reason, changed_at)
         VALUES (?, ?, ?, ?, ?)`,
        [
          candidate.role_code,
          newRevision,
          req.user.email,
          'Panel member removed',
          now,
        ]
      );

      // Record activity
      await dbRun(
        `INSERT INTO activity_trail (role_code, candidate_id, action_type, actor_email, action_data, assessment_version_at_action, assessment_version_changed, created_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          candidate.role_code,
          candidateId,
          'panel_member_removed',
          req.user.email,
          JSON.stringify({ memberEmail: member.email }),
          candidate.assessment_version,
          1,
          now,
        ]
      );

      res.json({
        success: true,
        assessmentVersion: newVersion,
        revision: newRevision,
      });
    } catch (err) {
      console.error('Error removing panel member:', err);
      res.status(500).json({ error: 'Failed to remove panel member' });
    }
  }
);

// Record score
router.post('/api/candidates/:candidateId/score', requireAuth, async (req, res) => {
  const { candidateId } = req.params;
  const { score } = req.body;

  // Check permissions
  const canScore = await canScoreCandidate(req.user.role);
  if (!canScore) {
    return res.status(403).json({ error: 'Unauthorized' });
  }

  try {
    const candidate = await dbGet(
      `SELECT * FROM candidates WHERE id = ?`,
      [candidateId]
    );

    if (!candidate) {
      return res.status(404).json({ error: 'Candidate not found' });
    }

    // Validate score
    const validation = await validateScore(
      score,
      candidateId,
      candidate.current_stage,
      req.user.email
    );

    if (!validation.valid) {
      return res.status(400).json({ error: validation.error });
    }

    // Check if user is on panel
    const panelMember = await dbGet(
      `SELECT pm.id FROM panel_members pm
       JOIN panels p ON pm.panel_id = p.id
       WHERE p.candidate_id = ? AND p.assessment_version = ? AND pm.email = ?`,
      [candidateId, candidate.assessment_version, req.user.email]
    );

    if (!panelMember) {
      return res.status(403).json({ error: 'Not assigned to this candidate' });
    }

    const now = new Date().toISOString();

    // Insert or update score
    await dbRun(
      `INSERT OR REPLACE INTO scores (candidate_id, assessment_version, panel_member_email, score, recorded_at)
       VALUES (?, ?, ?, ?, ?)`,
      [candidateId, candidate.assessment_version, req.user.email, score, now]
    );

    // Record activity
    await dbRun(
      `INSERT INTO activity_trail (role_code, candidate_id, action_type, actor_email, action_data, assessment_version_at_action, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?)`,
      [
        candidate.role_code,
        candidateId,
        'score_recorded',
        req.user.email,
        JSON.stringify({ score }),
        candidate.assessment_version,
        now,
      ]
    );

    // Increment vacancy revision
    const revisionResult = await dbGet(
      `SELECT revision_number FROM vacancy_revisions
       WHERE role_code = ? ORDER BY revision_number DESC LIMIT 1`,
      [candidate.role_code]
    );

    const currentRevision = revisionResult?.revision_number || 1;
    const newRevision = currentRevision + 1;

    await dbRun(
      `INSERT INTO vacancy_revisions (role_code, revision_number, changed_by, change_reason, changed_at)
       VALUES (?, ?, ?, ?, ?)`,
      [
        candidate.role_code,
        newRevision,
        req.user.email,
        'Score recorded',
        now,
      ]
    );

    res.json({
      success: true,
      score,
      revision: newRevision,
    });
  } catch (err) {
    console.error('Error recording score:', err);
    res.status(500).json({ error: 'Failed to record score' });
  }
});

